-- The daily / weekly / monthly mission programme, and the 28 participation
-- actions it needs.
--
-- Supplied as three spreadsheets: 730 daily missions, 104 weekly, 36 monthly.
-- Every one names an ACTION CODE, and missions.action_code is a foreign key
-- into participation_actions -- where 27 of the 28 codes used did not exist.
-- So the actions have to be created first, or not one mission can be inserted.
--
-- POINT VALUES ARE A DELIBERATE, CONSERVATIVE STARTING POINT.
-- Roughly: passive discovery 1-2, light engagement 1-2, real contribution
-- 5-10. Every one is editable in the admin, and every one is capped per day
-- so no single action can be farmed.
--
-- NINE ACTIONS ARE WORTH ZERO POINTS ON PURPOSE. badge_unlock,
-- achievement_unlock, passport_stamp, challenge_complete, streak_maintain,
-- score_progress, ranking_progress and compound_mission are DERIVED -- they
-- happen because the engine already awarded points for whatever caused them.
-- Paying again would double-count a member's score. They exist so missions
-- can key off them, not so anyone earns from them.
--
-- Mission targets and rewards (daily 1 step / 5 pts, weekly 3 / 25, monthly
-- 10 / 100) are starting values: the spreadsheets specify no targets, and a
-- weekly mission that completes on a single click would be meaningless. The
-- admin can change any of them.

-- 'monthly' becomes a real mission type. Nothing uses it today, so widening
-- the CHECK cannot invalidate an existing row.
ALTER TABLE missions DROP CONSTRAINT IF EXISTS missions_mission_type_check;
ALTER TABLE missions ADD CONSTRAINT missions_mission_type_check
  CHECK (mission_type IN ('daily', 'weekly', 'monthly', 'challenge'));

   counts_for_streak, counts_as_meaningful, counts_as_contribution, counts_for_active_month)
VALUES
  ('member_discover', 'Discovered a member', 'consumption', 1, 10, TRUE, FALSE, FALSE, TRUE),
  ('business_discover', 'Discovered a business', 'consumption', 1, 10, TRUE, FALSE, FALSE, TRUE),
  ('marketplace_discover', 'Explored the marketplace', 'consumption', 1, 10, TRUE, FALSE, FALSE, TRUE),
  ('article_read_complete', 'Read an article', 'consumption', 2, 10, TRUE, FALSE, FALSE, TRUE),
  ('article_audio_listen', 'Listened to an article', 'consumption', 2, 5, TRUE, FALSE, FALSE, TRUE),
  ('video_watch', 'Watched a video', 'consumption', 2, 5, TRUE, FALSE, FALSE, TRUE),
  ('like_content', 'Liked something', 'consumption', 1, 20, TRUE, FALSE, FALSE, TRUE),
  ('save_content', 'Saved something', 'consumption', 2, 20, TRUE, FALSE, FALSE, TRUE),
  ('comment_create', 'Wrote a comment', 'contribution', 5, 10, TRUE, TRUE, TRUE, TRUE),
  ('review_create', 'Wrote a review', 'contribution', 5, 5, TRUE, TRUE, TRUE, TRUE),
  ('content_submit', 'Submitted content', 'contribution', 10, 5, TRUE, TRUE, TRUE, TRUE),
  ('gallery_submit_or_interact', 'Took part in the gallery', 'contribution', 5, 10, TRUE, TRUE, TRUE, TRUE),
  ('content_share', 'Shared something', 'contribution', 3, 10, TRUE, FALSE, TRUE, TRUE),
  ('profile_action', 'Updated their profile', 'contribution', 2, 3, FALSE, FALSE, FALSE, TRUE),
  ('purpose_action', 'Set what they are plugging into', 'contribution', 2, 3, FALSE, FALSE, FALSE, TRUE),
  ('member_follow', 'Followed a member', 'social', 2, 20, TRUE, FALSE, FALSE, TRUE),
  ('recognition_nominate', 'Nominated someone', 'social', 3, 5, TRUE, TRUE, TRUE, TRUE),
