  ('competition_vote', 'Voted in a competition', 'competitive', 1, 20, TRUE, FALSE, FALSE, TRUE),
  ('competition_enter', 'Entered a competition', 'competitive', 5, 3, TRUE, TRUE, TRUE, TRUE),
  ('ranking_progress', 'Moved up the rankings', 'competitive', 0, NULL, FALSE, FALSE, FALSE, TRUE),
  ('badge_unlock', 'Unlocked a badge', 'achievement', 0, NULL, FALSE, FALSE, FALSE, TRUE),
