-- rotate_monthly_challenge() picks from mission_type = 'challenge'. Now that
-- monthly challenges are stored as 'monthly', it would never see a single one
-- of the 36 without this. Both types are accepted, so any existing 'challenge'
-- row keeps rotating exactly as it did before.
CREATE OR REPLACE FUNCTION rotate_monthly_challenge() RETURNS VARCHAR AS $BODY$
DECLARE
  v_month_start DATE := date_trunc('month', CURRENT_DATE)::DATE;
  v_month_end   DATE := (date_trunc('month', CURRENT_DATE) + INTERVAL '1 month - 1 day')::DATE;
  v_code        VARCHAR;
BEGIN
  IF EXISTS (SELECT 1 FROM monthly_challenge_rotation WHERE month_start = v_month_start) THEN
    RETURN (SELECT mission_code FROM monthly_challenge_rotation WHERE month_start = v_month_start);
  END IF;

  -- Prefers one never used before, then the least recently used, so a
  -- 36-month catalogue runs three years without repeating itself.
  SELECT m.code INTO v_code
    FROM missions m
    LEFT JOIN monthly_challenge_rotation r ON r.mission_code = m.code
   WHERE m.mission_type IN ('monthly', 'challenge') AND m.is_enabled = TRUE
   GROUP BY m.code
   ORDER BY MAX(r.month_start) NULLS FIRST, RANDOM()
   LIMIT 1;

  IF v_code IS NULL THEN RETURN NULL; END IF;

  VALUES (v_code, v_month_start, v_month_end)
  ON CONFLICT (month_start) DO NOTHING;
  RETURN v_code;
END;
$BODY$ LANGUAGE plpgsql;
